function addEnemy(big=false){let a=rand(0,TAU),r=rand(9,12);let tries=0,x=Math.cos(a)*r,z=Math.sin(a)*r;while(dist({x,z},player)<7&&tries++<20){a+=.7;x=Math.cos(a)*r;z=Math.sin(a)*r}let hp=big?6:3;enemies.push({x,z,hp,max:hp,speed:big?1.18:rand(1.3,1.8),cool:rand(.8,2),t:rand(0,TAU),flash:0,big})}
function spawnWave(){let count=player.wave===1?4:player.wave===2?6:7;for(let i=0;i<count;i++)addEnemy(player.wave===3&&i===0);spawnTimer=0}
function updateUI(){ui.score.textContent=String(player.score).padStart(4,'0');ui.kills.textContent=String(player.kills).padStart(2,'0');ui.wave.textContent=String(player.wave).padStart(2,'0');ui.health.style.width=player.hp+'%';ui.health.style.background=player.hp<30?'#ff4d85':'#54f4e7';ui.healthNum.textContent=Math.ceil(player.hp);ui.ammo.textContent=player.reload>0?'..':String(player.ammo).padStart(2,'0');ui.objective.textContent=exitOpen?'EXTRACTION OPEN':`${enemies.length} INTRUDERS REMAIN`}
