 for(let i=shots.length-1;i>=0;i--){let s=shots[i];s.x+=s.vx*dt;s.z+=s.vz*dt;s.life-=dt;if(s.enemy&&Math.hypot(s.x-player.x,s.z-player.z)<.45){damage(9);particlesAt(s.x,.9,s.z,'#ff4d85',5);shots.splice(i,1)}else if(s.life<=0||Math.abs(s.x)>14||Math.abs(s.z)>14)shots.splice(i,1)}
